[3685] = "Rune",
-- 577a2fa4 English: Rune Spell ID
[3686] = "ID du sort de rune",
-- b84ca6e3 English: Rune ID
[3687] = "ID de rune",
-- a698651e English: Matches when a Season of Discovery rune is engraved on one of your equipped
--     items. Passive runes count too, which a known-spell test cannot see.
[3688] = "Correspond quand une rune de Saison de la découverte est gravée sur l'un de vos objets équipés. Les runes passives comptent aussi, ce qu'un test de sort connu ne peut pas voir.",
-- 1daa202b English: Pick one of your known runes by equipment slot. The rune is saved by the first
--     spell it teaches, so a shared rotation names it on any character.
[3689] = "Choisissez l'une de vos runes connues par emplacement d'équipement. La rune est enregistrée par le premier sort qu'elle enseigne, de sorte qu'une rotation partagée la désigne sur n'importe quel personnage.",
-- 8151a8cf English: Enter a spell the rune teaches, or the rune's own ID (its skill line ability
--     ID) for a rune that teaches no spell. Entering one clears the other.
[3690] = "Saisissez un sort qu'enseigne la rune, ou l'ID propre de la rune (son ID de capacité de compétence) pour une rune qui n'enseigne aucun sort. En saisir un efface l'autre.",
-- 868afb4d English: Engraving exists only on Season of Discovery realms. Elsewhere, and until your
--     runes have loaded after logging in, this condition is unavailable rather than false,
--     including under NOT. The Phase 7 shoulder runes are not engravings and are not seen. This is
--     not the Death Knight Rune condition.
[3691] = "La gravure n'existe que sur les royaumes de Saison de la découverte. Ailleurs, et tant que vos runes ne sont pas chargées après la connexion, cette condition est indisponible plutôt que fausse, y compris sous NOT. Les runes d'épaulières de la phase 7 ne sont pas des gravures et ne sont pas détectées. Ce n'est pas la condition Rune du chevalier de la mort.",
-- 2cfaca8e English: Your talents cannot be listed right now (%s). A node ID entered below is kept
--     and evaluated.
[3692] = "Vos talents ne peuvent pas être listés pour le moment (%s). Un ID de nœud saisi ci-dessous est conservé et évalué.",
-- 0d2b4c68 English: Talents can be listed only for your own class. A node ID entered below is kept
--     and evaluated.
[3693] = "Les talents ne peuvent être listés que pour votre propre classe. Un ID de nœud saisi ci-dessous est conservé et évalué.",
